INSERT INTO quiz_questions (quiz_id, question_text, scenario_context, options, correct_answer_index, explanation, order_index) VALUES
('a1000001-0000-0000-0000-000000000001','What framework does this course primarily teach?','A friend asks what methodology you are studying.','["Waterfall", "Scrum", "PRINCE2", "Kanban"]'::jsonb,1,'This course is centered on the Scrum framework.',5),
('a1000001-0000-0000-0000-000000000001','Which industries use Scrum Masters according to the course?','You are researching potential employers.','["Only software companies", "Only startups", "Aerospace technology finance and more", "Only non-profits"]'::jsonb,2,'Scrum is used across aerospace technology finance and many other industries.',6),
('a1000001-0000-0000-0000-000000000001','What is one key outcome after completing this course?','You are setting learning goals at the start.','["Become a software developer", "Be prepared for Scrum Master certification exams", "Learn Gantt chart creation", "Obtain a PMP credential automatically"]'::jsonb,1,'The course prepares students for Scrum Master certification exams.',7),
('a1000001-0000-0000-0000-000000000001','What teaching approach does this course use beyond theory?','You want to know if the course involves practical application.','["Memorization of terms only", "Hands-on practice with real-life scenarios", "Reading textbooks exclusively", "Watching recorded lectures only"]'::jsonb,1,'The course combines theory with hands-on practice and real-life scenarios.',8),
('a1000001-0000-0000-0000-000000000001','What is the Scrum Master primary value to an organization?','An executive asks you to justify the Scrum Master role.','["Writing code faster", "Managing budgets", "Enabling teams to deliver value continuously through Agile practices", "Creating detailed project plans"]'::jsonb,2,'A Scrum Master enables continuous value delivery by coaching teams and removing obstacles.',9),
('a1000001-0000-0000-0000-000000000001','Which statement best describes demand for Scrum Masters today?','You are researching job market trends.','["Demand is declining due to AI", "Demand is stable but low", "Demand is high as organizations adopt Agile at scale", "Only large enterprises hire Scrum Masters"]'::jsonb,2,'As Agile adoption grows globally demand for Scrum Masters continues to rise.',10),
('a1000001-0000-0000-0000-000000000001','What mindset should a student bring to this course?','Prof. Didier opens the first lesson and sets expectations.','["Passive consumption of information", "Active learning and application of concepts", "Memorizing definitions for a test", "Competing with other students"]'::jsonb,1,'Active learning leads to the best outcomes in this course.',11),
('a1000001-0000-0000-0000-000000000001','What does the Scrum Guide define as the Scrum Master core responsibility?','You are asked to summarize the Scrum Guide position on the SM role.','["Assign tasks to team members", "Own the product roadmap", "Accountable for the Scrum team effectiveness", "Approve all user stories"]'::jsonb,2,'The Scrum Master is accountable for the Scrum team effectiveness.',12),
('a1000001-0000-0000-0000-000000000001','What is empiricism in the context of Scrum?','You are explaining Scrum theoretical foundation to a new colleague.','["Managing projects by prediction only", "Making decisions based on observation experience and evidence", "Following a fixed process without feedback", "Maximizing team velocity at all costs"]'::jsonb,1,'Scrum is founded on empiricism - decisions are based on what is observed and known.',13),
('a1000001-0000-0000-0000-000000000001','What does servant leadership mean in the Scrum context?','A hiring manager asks you to define servant leadership.','["The SM serves coffee to the team", "The SM prioritizes the needs of the team over personal authority", "The SM reports to every team member", "The SM avoids making any decisions"]'::jsonb,1,'Servant leadership means prioritizing enabling and supporting the team rather than exercising authority.',14),
('a1000001-0000-0000-0000-000000000001','Which Scrum value is demonstrated when team members share progress openly?','During a Daily Scrum each member updates the team on blockers and progress.','["Courage", "Commitment", "Transparency", "Focus"]'::jsonb,2,'Transparency is reflected when team members openly share their work and impediments.',15),
('a1000001-0000-0000-0000-000000000001','What is the time-box for a Sprint in Scrum?','Your team is deciding how long each Sprint should be.','["Exactly 2 weeks always", "One month maximum", "Six weeks minimum", "Depends on the project manager"]'::jsonb,1,'A Sprint is time-boxed to one month or less.',16),
('a1000001-0000-0000-0000-000000000001','How does the Scrum Master support the Product Owner?','A Product Owner struggles to communicate priorities to the team.','["By writing user stories for them", "By helping them understand and apply effective Product Backlog management", "By approving the product vision", "By presenting the backlog to stakeholders instead"]'::jsonb,1,'The SM supports the PO by helping them manage the Product Backlog effectively.',17),
('a1000001-0000-0000-0000-000000000001','What happens at a Sprint Retrospective?','Your team just finished Sprint 3 and is meeting to discuss the process.','["Plan the next Sprint backlog", "Review the product increment with stakeholders", "Inspect how the last Sprint went and identify improvements", "Assign tasks for the upcoming Sprint"]'::jsonb,2,'The Retrospective is for the team to inspect their process and identify improvements.',18),
('a1000001-0000-0000-0000-000000000001','What is the Definition of Done in Scrum?','A developer asks how they know when a user story is truly complete.','["When the Product Owner verbally approves it", "A formal description of the quality standards a product increment must meet", "When all tests pass in staging", "When the Scrum Master signs off"]'::jsonb,1,'The Definition of Done is a shared understanding of quality criteria for completed work.',19),
('a1000001-0000-0000-0000-000000000002','Which of the following is NOT a responsibility of a Scrum Master?','An interviewer asks you to describe what a Scrum Master does not do.','["Facilitating Scrum events", "Coaching the team on Agile practices", "Assigning tasks to developers", "Removing impediments"]'::jsonb,2,'Scrum Masters do not assign tasks - teams self-organize.',5),
('a1000001-0000-0000-0000-000000000002','How does a Scrum Master benefit the organization beyond the team?','A VP asks what value the Scrum Master brings to the broader company.','["By managing project budgets", "By coaching the organization in Agile adoption and removing systemic impediments", "By writing technical documentation", "By replacing the HR function"]'::jsonb,1,'Scrum Masters benefit the organization by coaching Agile adoption and removing systemic barriers.',6),
('a1000001-0000-0000-0000-000000000002','What is the relationship between the Scrum Master and the Developers?','A new team member asks how the Scrum Master fits into the team structure.','["The SM is the team boss", "The SM coaches the developers and helps them self-organize", "The SM reports to the developers", "The SM and developers work in separate silos"]'::jsonb,1,'The Scrum Master coaches developers and helps the team self-organize.',7),
('a1000001-0000-0000-0000-000000000002','What does it mean for a Scrum Master to protect the team?','Stakeholders keep interrupting the team during a Sprint with new requests.','["Physically guarding the office", "Shielding the team from external disruptions and scope changes mid-Sprint", "Preventing all communication with stakeholders", "Filing HR complaints"]'::jsonb,1,'Protecting the team means shielding them from mid-Sprint scope changes and external distractions.',8),
('a1000001-0000-0000-0000-000000000002','Which Scrum event does the Scrum Master typically facilitate?','Your team is planning the agenda for the week ceremonies.','["Only the Daily Scrum", "Sprint Planning Daily Scrum Sprint Review and Sprint Retrospective", "Only Sprint Review", "Only Sprint Retrospective"]'::jsonb,1,'The Scrum Master facilitates or ensures all four Scrum events are productive.',9),
('a1000001-0000-0000-0000-000000000002','What is an impediment in Scrum?','A developer tells you they cannot complete their task due to a blocked API access.','["A low-priority backlog item", "Any obstacle that slows or blocks the team progress", "A stakeholder complaint", "A defect in the product"]'::jsonb,1,'An impediment is any obstacle that blocks the team progress.',10),
('a1000001-0000-0000-0000-000000000002','How does a Scrum Master handle a team conflict?','Two developers disagree on the technical approach for a user story.','["Decides for the team which approach to use", "Ignores it and hopes it resolves itself", "Facilitates a conversation to help the team reach their own resolution", "Escalates immediately to HR"]'::jsonb,2,'A Scrum Master facilitates conflict resolution by guiding the team to resolve it themselves.',11),
('a1000001-0000-0000-0000-000000000002','What is the primary benefit of daily Scrums for a development team?','A stakeholder questions why the team needs to meet every day.','["To report status to management", "To synchronize work and identify impediments quickly", "To update the Product Backlog", "To review completed user stories"]'::jsonb,1,'Daily Scrums help the team synchronize and surface impediments early.',12),
('a1000001-0000-0000-0000-000000000002','Why is psychological safety important for a Scrum team?','Team members are hesitant to raise issues during the Retrospective.','["It prevents the team from challenging the Product Owner", "It allows team members to speak up experiment and fail safely", "It removes the need for a Scrum Master", "It limits the team workload"]'::jsonb,1,'Psychological safety allows team members to raise concerns and learn from failures without fear.',13),
('a1000001-0000-0000-0000-000000000002','What is the Scrum Master role during Sprint Planning?','The team is about to start Sprint Planning for the upcoming Sprint.','["Selecting which backlog items to work on", "Ensuring the event happens and helping the team understand its purpose", "Writing acceptance criteria for each story", "Approving the Sprint Goal"]'::jsonb,1,'During Sprint Planning the SM ensures the event is productive and helps the team understand the process.',14),
('a1000001-0000-0000-0000-000000000002','What does continuous improvement mean in a Scrum context?','Your team completed a Retrospective and identified three process improvements.','["Releasing features faster without quality checks", "Regularly inspecting and adapting processes to become more effective", "Replacing team members who underperform", "Adding more tools and ceremonies"]'::jsonb,1,'Continuous improvement means regularly inspecting how the team works and adapting to improve.',15),
('a1000001-0000-0000-0000-000000000002','What is velocity in Scrum?','Your Product Owner asks how to predict how much work will be done next Sprint.','["The speed at which the SM resolves impediments", "The amount of work a team completes in a Sprint used to forecast future capacity", "The number of bugs fixed per Sprint", "The time it takes to run a Daily Scrum"]'::jsonb,1,'Velocity measures how much work a team completes per Sprint enabling forecasting.',16),
('a1000001-0000-0000-0000-000000000002','How does a Scrum Master add value to the Sprint Review?','The team is preparing for the Sprint Review with stakeholders.','["By presenting all the work instead of the developers", "By ensuring the event occurs and that feedback is captured and acted upon", "By writing the Sprint report for stakeholders", "By approving what the team will demo"]'::jsonb,1,'In the Sprint Review the SM ensures the event is productive and stakeholder feedback is captured.',17),
('a1000001-0000-0000-0000-000000000002','What is the Scrum Master stance on metrics?','A manager wants to use velocity as a performance review metric for individuals.','["Fully supports individual velocity tracking", "Uses metrics to coach improvement not to evaluate individuals", "Refuses to track any metrics", "Reports individual metrics to HR"]'::jsonb,1,'A good SM uses metrics to foster improvement not to evaluate or pressure individuals.',18),
('a1000001-0000-0000-0000-000000000002','What does self-organization mean for a Scrum team?','A new SM asks how tasks get assigned if there is no project manager.','["Team members work alone without coordination", "The team collectively decides how to do the work without being directed", "The Product Owner assigns all tasks", "The SM assigns tasks during Daily Scrum"]'::jsonb,1,'Self-organization means the team decides how to accomplish work without external direction.',19),
('a1000001-0000-0000-0000-000000000003','What separates a great Scrum Master from an average one?','You are reading expert interviews about top Scrum Masters.','["Knowing every Agile framework by heart", "Deep coaching ability and systems thinking", "Running the fastest Daily Scrums", "Having a computer science degree"]'::jsonb,1,'Expert SMs are distinguished by coaching ability and systems thinking.',5),
('a1000001-0000-0000-0000-000000000003','What do experts say about the SM role in a remote team?','Your organization has shifted to fully remote work.','["The SM role is less important remotely", "Remote SMs must be more intentional about building trust and communication", "Remote teams do not need Scrum Masters", "All ceremonies should be skipped remotely"]'::jsonb,1,'Remote SMs must be more deliberate about fostering connection and communication.',6),
('a1000001-0000-0000-0000-000000000003','How do expert Scrum Masters approach stakeholder management?','A senior executive keeps bypassing the Scrum process.','["Always comply with executive requests immediately", "Ignore stakeholders outside the team", "Educate stakeholders on Scrum and find ways to engage them constructively", "Escalate to HR every time"]'::jsonb,2,'Expert SMs educate stakeholders on Scrum and find constructive ways to engage them.',7),
('a1000001-0000-0000-0000-000000000003','What role does data play in an expert Scrum Master practice?','You want to demonstrate the team improvement to leadership.','["Data is irrelevant in Agile", "Expert SMs use data like burndown charts and cycle time to surface insights", "Only developers should track data", "Data should be hidden from stakeholders"]'::jsonb,1,'Expert SMs use data transparently to foster conversations about improvement.',8),
('a1000001-0000-0000-0000-000000000003','What is the biggest misconception about the Scrum Master role?','A colleague tells you that Scrum Masters are just meeting facilitators.','["That they are unnecessary", "That they are just note-takers", "That they are only meeting facilitators rather than coaches and change agents", "That they are too expensive"]'::jsonb,2,'The biggest misconception is that SMs only run meetings - they are coaches and change agents.',9),
('a1000001-0000-0000-0000-000000000003','What is systems thinking in the context of Scrum Mastery?','Your team keeps experiencing the same impediment every Sprint.','["Thinking about IT infrastructure", "Seeing the team as part of a larger system and addressing root causes", "Focusing only on the current Sprint", "Outsourcing the problem to management"]'::jsonb,1,'Systems thinking means addressing root causes within the broader organizational context.',10),
('a1000001-0000-0000-0000-000000000003','How should a SM respond when asked to be the team project manager?','Your manager tells you to start managing the team tasks and reporting deadlines.','["Accept the role immediately", "Refuse all communication with management", "Clarify the SM role and coach the organization on the difference", "Start using Gantt charts alongside Scrum"]'::jsonb,2,'A SM should clarify their distinct role and use it as an opportunity to educate the organization.',11),
('a1000001-0000-0000-0000-000000000003','What do experts say about SMs who also code or do technical work?','You are a developer who just became a SM on the same team.','["It is always a best practice to do both", "It creates a conflict of interest and splits focus - the SM role should be primary", "Technical SMs are always more effective", "Only non-technical people should be SMs"]'::jsonb,1,'Combining SM and developer roles splits focus and can compromise the SM neutrality.',12),
('a1000001-0000-0000-0000-000000000003','What is the significance of asking powerful questions?','A team member comes to you with a problem and expects you to solve it.','["It wastes time when direct answers are more efficient", "Powerful questions help team members discover solutions themselves", "It is a technique used only in coaching sessions", "It shows the SM does not know the answer"]'::jsonb,1,'Powerful questions build team problem-solving capability rather than creating dependency.',13),
('a1000001-0000-0000-0000-000000000003','When should a SM escalate an impediment?','An impediment has persisted for two Sprints and is outside the team control.','["Never - the SM should always resolve it alone", "Immediately after it is raised in the Daily Scrum", "When the team cannot resolve it and it requires organizational authority", "Only at the quarterly review"]'::jsonb,2,'Escalation is appropriate when an impediment requires organizational authority to remove.',14),
('a1000001-0000-0000-0000-000000000003','What does a SM do when a team is performing well with no visible impediments?','Your team has been running smoothly for three Sprints.','["Takes a vacation since there is no work", "Focuses on continuous improvement team growth and organizational coaching", "Starts managing the backlog", "Requests a new team assignment"]'::jsonb,1,'Even in high-performing teams the SM focuses on deeper improvement and organizational value.',15),
('a1000001-0000-0000-0000-000000000003','How does an expert SM build trust with a new team?','You are joining an existing Scrum team as their new SM.','["By immediately changing all their processes", "By listening observing and demonstrating value before making recommendations", "By asserting authority in the first Sprint", "By replacing team ceremonies with new ones"]'::jsonb,1,'Trust is built by listening and observing first then demonstrating value.',16),
('a1000001-0000-0000-0000-000000000003','What is the difference between coaching and mentoring?','A junior developer asks you to teach them everything about Scrum.','["There is no difference", "Coaching draws out the person own answers while mentoring shares the SM experience", "Mentoring is for personal issues coaching is for technical issues", "Coaching is only for managers"]'::jsonb,1,'Coaching asks questions to help someone discover their own answers while mentoring shares knowledge.',17),
('a1000001-0000-0000-0000-000000000003','What should a SM do if the team ignores Scrum principles?','The team skips the Retrospective because they feel it is a waste of time.','["Force the team to attend by reporting them to management", "Accept it and remove the Retrospective permanently", "Have an honest conversation about the purpose and value of the ceremony", "Replace the team"]'::jsonb,2,'A SM addresses resistance through honest conversation about the value of Scrum events.',18),
('a1000001-0000-0000-0000-000000000003','How do expert SMs measure their own success?','Your annual review asks how you measure your effectiveness.','["By the number of ceremonies they run per Sprint", "By the team growing autonomy delivery quality and ability to self-improve", "By how many impediments they personally resolved", "By their certification level"]'::jsonb,1,'Expert SMs measure success by team autonomy delivery quality and continuous self-improvement.',19),
('a1000001-0000-0000-0000-000000000004','Which communication skill is most critical for a Scrum Master?','You are preparing for a SM job interview.','["Writing long technical reports", "Active listening and facilitating clear dialogue", "Public speaking at conferences", "Speed-reading documentation"]'::jsonb,1,'Active listening and clear facilitation are the most critical SM communication skills.',5),
('a1000001-0000-0000-0000-000000000004','Why is emotional intelligence important for a Scrum Master?','A team member appears frustrated but says everything is fine.','["It helps write better user stories", "It helps recognize and respond to emotional cues to support the team", "It replaces the need for certifications", "It is only relevant in HR roles"]'::jsonb,1,'High EQ allows a SM to detect unspoken issues and respond with empathy and skill.',6),
('a1000001-0000-0000-0000-000000000004','What is facilitation in the Scrum Master skill inventory?','You are running a Retrospective with a team that goes off-topic.','["Controlling who speaks and enforcing silence", "Guiding a group through a structured process to achieve a productive outcome", "Documenting meeting minutes only", "Presenting conclusions to the team"]'::jsonb,1,'Facilitation is guiding a group through productive discussions without controlling the outcome.',7),
('a1000001-0000-0000-0000-000000000004','How does a SM demonstrate continuous learning?','Your manager asks how you stay current in an evolving Agile landscape.','["By avoiding all new frameworks", "By pursuing certifications attending communities of practice and reading widely", "By relying solely on past experience", "By asking team members to teach them everything"]'::jsonb,1,'Continuous learning through certifications communities and reading keeps SMs effective.',8),
('a1000001-0000-0000-0000-000000000004','What is the value of understanding business context for a SM?','The PO mentions revenue goals when discussing backlog priorities.','["Business context is irrelevant to the SM role", "Understanding business goals helps the SM facilitate better prioritization and stakeholder alignment", "Only the PO needs to understand business context", "It helps the SM become a PO eventually"]'::jsonb,1,'Business context helps the SM facilitate more meaningful conversations about value and priority.',9),
('a1000001-0000-0000-0000-000000000004','Which best demonstrates a SM conflict resolution skill?','Two senior developers are in a heated debate over architecture during Sprint Planning.','["Taking sides with the more senior developer", "Ending Sprint Planning early", "Creating space for both views and guiding the team to a shared decision", "Reporting the conflict to HR immediately"]'::jsonb,2,'Conflict resolution involves creating a safe space for all views and helping the team decide.',10),
('a1000001-0000-0000-0000-000000000004','Why is adaptability a key SM skill?','The organization suddenly shifts strategy mid-quarter.','["So the SM can change jobs easily", "Because Scrum environments are dynamic and the SM must adjust coaching approaches constantly", "To help the SM avoid difficult situations", "Adaptability is not a SM skill"]'::jsonb,1,'Adaptability lets the SM respond effectively as team product and organizational needs change.',11),
('a1000001-0000-0000-0000-000000000004','What is the purpose of a skills matrix for a Scrum team?','You want to identify gaps that might slow the team delivery capacity.','["To rank team members by performance", "To visualize team skill distribution and identify learning opportunities", "To justify salary increases", "To replace the Definition of Done"]'::jsonb,1,'A skills matrix helps the team see where skills are concentrated or missing.',12),
('a1000001-0000-0000-0000-000000000004','How does a SM develop their coaching skills over time?','You want to become a more effective coach for your team.','["By reading the Scrum Guide once a year", "Through deliberate practice feedback supervision and studying coaching models", "By attending every Scrum ceremony", "By becoming the team manager"]'::jsonb,1,'Coaching skills develop through deliberate practice feedback loops and studying frameworks.',13),
('a1000001-0000-0000-0000-000000000004','What does holding the space mean in facilitation?','The team goes silent after a difficult question during a Retrospective.','["Filling silence with your own answers immediately", "Booking the conference room in advance", "Maintaining a safe environment that allows the team to reflect at their own pace", "Scheduling the next meeting"]'::jsonb,2,'Holding the space means maintaining a safe environment and allowing silence and reflection.',14),
('a1000001-0000-0000-0000-000000000004','What skill helps a SM build credibility with skeptical stakeholders?','A senior stakeholder questions your value.','["Aggressively promoting Agile", "Demonstrating business acumen and linking Scrum outcomes to organizational goals", "Avoiding all stakeholder interactions", "Citing the Scrum Guide repeatedly"]'::jsonb,1,'Credibility with skeptical stakeholders comes from connecting Scrum outcomes to business value.',15),
('a1000001-0000-0000-0000-000000000004','What is the role of transparency in a SM skill set?','The team is behind on Sprint goals but the SM has not communicated this to the PO.','["Transparency is optional when information may cause concern", "Transparency is a core skill - ensure all relevant information is visible to those who need it", "Only the PO should be transparent", "Transparency applies only during reviews"]'::jsonb,1,'Transparency is a foundational SM skill - ensuring relevant information is visible.',16),
('a1000001-0000-0000-0000-000000000004','How does a SM use retrospective techniques effectively?','Your team says the Retrospective always feels the same.','["Cancel retrospectives to save time", "Vary techniques like Start Stop Continue 4Ls and Sailboat to keep engagement high", "Let the team run it with no structure", "Use only one technique forever for consistency"]'::jsonb,1,'Rotating facilitation techniques keeps Retrospectives fresh and increases engagement.',17),
('a1000001-0000-0000-0000-000000000004','What does cross-functional understanding mean for a SM?','Your team includes designers QA engineers and backend developers who rarely collaborate.','["Learning to do everyone job", "Understanding each discipline contributions and facilitating collaboration across them", "Assigning cross-functional tasks to every team member", "Replacing specialists with generalists"]'::jsonb,1,'Cross-functional understanding helps the SM bridge communication gaps and facilitate collaboration.',18),
('a1000001-0000-0000-0000-000000000004','Why should a SM develop organizational awareness?','A policy change is blocking a team tool purchase for two Sprints.','["To climb the corporate ladder", "To navigate and influence the organizational systems that impact team performance", "To become a Product Manager", "It is not relevant to the SM role"]'::jsonb,1,'Organizational awareness allows the SM to address impediments that originate outside the team.',19),
('a1000001-0000-0000-0000-000000000005','What do expert SMs say about the importance of curiosity?','An experienced SM mentor tells you the one trait they look for.','["Curiosity is less important than certification", "Curious SMs ask better questions and discover deeper root causes", "Only curiosity about technology matters", "Curiosity can be a distraction"]'::jsonb,1,'Curiosity drives better questions and more effective coaching.',5),
('a1000001-0000-0000-0000-000000000005','What do experts identify as the most underrated SM skill?','You are reading a panel discussion of senior Scrum Masters.','["Running Daily Scrums efficiently", "Active listening - truly understanding before responding", "Writing Sprint reports", "Managing tool configurations in Jira"]'::jsonb,1,'Experts consistently cite active listening as the most underrated and impactful SM skill.',6),
('a1000001-0000-0000-0000-000000000005','How do experienced SMs approach a team that resists Agile?','Your new team says Scrum is just overhead.','["Force compliance by enforcing all ceremonies strictly", "Ignore their concerns and proceed as planned", "Meet them where they are understand frustrations and build trust through small wins", "Replace resistant team members"]'::jsonb,2,'Expert SMs build trust by meeting teams where they are and demonstrating value gradually.',7),
('a1000001-0000-0000-0000-000000000005','What is the value of attending communities of practice?','You are deciding whether to join a local Agile community group.','["It is mostly a social activity with little value", "It provides exposure to diverse experiences techniques and peer coaching", "Only mandatory for certification renewal", "It replaces formal training"]'::jsonb,1,'Communities of practice expose SMs to diverse practices and peer coaching.',8),
('a1000001-0000-0000-0000-000000000005','What skill helps a SM lead organizational change beyond their team?','Your company wants to scale Agile across all departments.','["Project management certification", "Change management skills and stakeholder influence", "Database administration", "Knowledge of accounting principles"]'::jsonb,1,'Change management skills allow SMs to guide organizational Agile transformations.',9),
('a1000001-0000-0000-0000-000000000005','How should a SM handle a technically superior team member who dismisses Scrum?','Your best developer openly says Scrum is a waste of time.','["Remove them from the team", "Agree with them publicly to avoid conflict", "Acknowledge their expertise explore concerns and connect Scrum value to what they care about", "Report them to the PO"]'::jsonb,2,'Effective SMs acknowledge expertise and make Scrum value relevant to individual goals.',10),
('a1000001-0000-0000-0000-000000000005','What role does pattern recognition play in advanced Scrum Mastery?','You notice that team velocity always drops in the third Sprint of every quarter.','["It is not relevant - every Sprint is unique", "Pattern recognition allows SMs to spot systemic issues before they become crises", "Only data analysts need pattern recognition", "It is only useful in the Retrospective"]'::jsonb,1,'Recognizing patterns allows a SM to intervene proactively rather than reactively.',11),
('a1000001-0000-0000-0000-000000000005','What do experts say about SMs with both Agile and business skills?','A recruiter tells you the most in-demand SMs have a business background.','["Business skills are irrelevant to coaching", "Combined Agile and business skills make SMs more credible organizational partners", "Business skills make SMs too focused on profit", "Only POs need business skills"]'::jsonb,1,'Business literacy combined with Agile expertise makes SMs more effective organizational partners.',12),
('a1000001-0000-0000-0000-000000000005','What is the significance of psychological models like SCARF for SMs?','You are preparing a workshop on team dynamics.','["They are only for therapists", "They help SMs understand human threat and reward responses to create safer team environments", "They are used only in HR evaluations", "They replace the need for Scrum values"]'::jsonb,1,'Models like SCARF help SMs design interactions that maximize team engagement.',13),
('a1000001-0000-0000-0000-000000000005','How do expert SMs stay humble despite years of experience?','A veteran SM mentor shares their philosophy.','["By claiming to know everything before asking questions", "By acknowledging every team is unique and approaching each with a learner mindset", "By avoiding feedback from team members", "By relying only on past successes"]'::jsonb,1,'Expert SMs maintain a learner mindset because each team is unique.',14),
('a1000001-0000-0000-0000-000000000005','What does holding a mirror mean as a SM technique?','Your team is not aware their estimation habits cause Sprint overload.','["Bringing a physical whiteboard to retros", "Reflecting observations back to the team to help them see their own patterns", "Criticizing team members in public", "Recording the team without their consent"]'::jsonb,1,'Holding a mirror means neutrally reflecting the team patterns back to prompt self-awareness.',15),
('a1000001-0000-0000-0000-000000000005','What is the relationship between Scrum Mastery and servant leadership?','A student asks you to connect the SM role to a broader leadership philosophy.','["They are unrelated concepts", "Servant leadership is the philosophical foundation of Scrum Mastery - serve first lead second", "Servant leadership means doing all team members work for them", "Only executives practice servant leadership"]'::jsonb,1,'Servant leadership is the core philosophy of Scrum Mastery - enable others rather than direct.',16),
('a1000001-0000-0000-0000-000000000005','Why is storytelling an important skill for a SM?','You need to convince leadership to invest in Agile coaching resources.','["It is not - data and spreadsheets are more persuasive", "Stories connect data to human experience and make a compelling case for change", "Storytelling is only for children education", "It replaces the need for metrics"]'::jsonb,1,'Storytelling connects data to human experience making complex arguments more persuasive.',17),
('a1000001-0000-0000-0000-000000000005','What is the most important question a SM can ask themselves daily?','You are building a daily reflection practice.','["How many impediments did I remove today?", "How many ceremonies did I run?", "How did I enable the team to be more effective today?", "How many hours did I work?"]'::jsonb,2,'The most powerful SM reflection is about enabling the team not personal output.',18),
('a1000001-0000-0000-0000-000000000005','What distinguishes a Level 3 SM from a Level 1?','You are mapping your SM growth trajectory.','["Level 3 has more certifications", "Level 3 influences the entire organization systems not just team ceremonies", "Level 3 manages more teams simultaneously", "Level 3 earns a higher salary automatically"]'::jsonb,1,'A Level 3 SM operates at the organizational level influencing culture and systems.',19),
('a1000001-0000-0000-0000-000000000006','What is typically the first thing a SM does at the start of their workday?','You are preparing for your first day as a SM.','["Checks and assigns tasks to team members", "Reviews the team progress checks for blockers and prepares for the Daily Scrum", "Writes the Sprint report", "Attends a management briefing"]'::jsonb,1,'A SM begins the day by reviewing team status and preparing to facilitate the Daily Scrum.',5),
('a1000001-0000-0000-0000-000000000006','How does a SM typically spend time between Scrum events?','A colleague asks what you do when not running ceremonies.','["Waits for the next ceremony to start", "Removes impediments coaches team members and engages with stakeholders", "Works on their own technical tasks", "Attends every meeting the PO has"]'::jsonb,1,'Between ceremonies the SM actively removes impediments coaches and builds relationships.',6),
('a1000001-0000-0000-0000-000000000006','What does a SM do when an impediment cannot be resolved the same day?','A team member raised a blocker that requires vendor approval.','["Removes it from the impediment log", "Tracks it visibly pursues escalation paths and updates the team on progress daily", "Tells the team to work around it without support", "Waits until the next Retrospective"]'::jsonb,1,'Persistent impediments are tracked visibly escalated appropriately and communicated regularly.',7),
('a1000001-0000-0000-0000-000000000006','Why does a SM invest time in 1:1 conversations with team members?','You schedule a weekly 1:1 with each team member.','["To evaluate their performance for HR purposes", "To build trust and surface concerns that might not emerge in group settings", "To assign personal targets and KPIs", "To replace the Daily Scrum"]'::jsonb,1,'1:1s build individual trust and surface concerns that people may not share in group settings.',8),
('a1000001-0000-0000-0000-000000000006','How does a SM prepare for Sprint Planning?','Sprint Planning is scheduled for tomorrow.','["Does nothing - the PO handles all preparation", "Ensures the backlog is refined the team is aligned on capacity and a clear Sprint Goal is possible", "Writes the Sprint plan the night before", "Books the meeting room only"]'::jsonb,1,'The SM prepares by confirming backlog refinement team capacity and conditions for a Sprint Goal.',9),
('a1000001-0000-0000-0000-000000000006','What is the SM role in backlog refinement?','The team and PO are struggling to break down a large feature.','["Write the user stories themselves", "Facilitate the refinement session to help the team and PO reach shared understanding", "Skip refinement since it is the PO job", "Assign story points to each item"]'::jsonb,1,'The SM facilitates refinement to help the team and PO reach shared understanding.',10),
('a1000001-0000-0000-0000-000000000006','What does a SM end-of-Sprint routine typically include?','Sprint 5 is wrapping up.','["Filing the Sprint report and archiving all tasks", "Facilitating the Sprint Review and Retrospective then preparing for the next Sprint Planning", "Closing all JIRA tickets manually", "Writing the next Sprint user stories"]'::jsonb,1,'End-of-Sprint routines include the Review Retrospective and preparation for the next Sprint.',11),
('a1000001-0000-0000-0000-000000000006','How does a SM handle multiple teams if they support more than one?','You have been assigned as SM for two teams simultaneously.','["Runs identical ceremonies for both teams at the same time", "Prioritizes time and attention carefully ensuring each team gets focused support", "Assigns one team to manage themselves", "Combines both teams into one"]'::jsonb,1,'When supporting multiple teams the SM carefully allocates time to ensure focused coaching.',12),
('a1000001-0000-0000-0000-000000000006','What is the SM daily goal in terms of team health?','You reflect at the end of each day on your team overall state.','["Ensuring 100% story point completion every day", "Monitoring team energy collaboration and morale to intervene early when needed", "Maximizing output metrics", "Reporting individual performance to management"]'::jsonb,1,'The SM monitors team health to intervene early and maintain a sustainable pace.',13),
('a1000001-0000-0000-0000-000000000006','What should a SM do when the Daily Scrum consistently runs over 15 minutes?','Your Daily Scrum has been running 30-40 minutes for three weeks.','["Extend the time-box permanently", "Accept it since longer meetings mean more collaboration", "Coach the team on the purpose of the Daily Scrum and introduce techniques to stay focused", "Cancel the Daily Scrum"]'::jsonb,2,'Chronic over-runs signal a facilitation opportunity - coach the team to keep to time-box.',14),
('a1000001-0000-0000-0000-000000000006','How does the SM handle a stakeholder who demands daily status updates?','A VP emails you every morning asking for a team status report.','["Writes a daily report to keep them happy", "Ignores the emails", "Engages the stakeholder and provides appropriate visibility through Scrum artifacts", "Adds the VP to the Daily Scrum"]'::jsonb,2,'The SM connects the stakeholder to appropriate Scrum artifacts and review events.',15),
('a1000001-0000-0000-0000-000000000006','What personal habits support SMs in performing their best?','You are building sustainable work habits as a new SM.','["Working as many hours as possible", "Reflective journaling seeking peer feedback and investing in their own learning continuously", "Avoiding all personal development", "Only attending company-mandated training"]'::jsonb,1,'Reflective practice peer feedback and continuous learning are essential SM habits.',16),
('a1000001-0000-0000-0000-000000000006','What does a typical SM week look like in terms of ceremony vs coaching time?','A mentor asks you to estimate how your time is distributed.','["100% ceremony facilitation", "About 20% ceremonies 80% coaching removing impediments and organizational engagement", "50% in management meetings", "Equal split between coding and ceremonies"]'::jsonb,1,'Ceremonies are a small fraction of SM time - the majority is coaching and relationship building.',17),
('a1000001-0000-0000-0000-000000000006','How does a SM contribute to the team technical excellence?','The team code quality has declined and technical debt is rising.','["Writes code to fix the technical debt", "Creates space for engineering practices by removing non-technical impediments", "Ignores technical issues as outside the SM role", "Reports the developers to their manager"]'::jsonb,1,'The SM supports technical excellence by creating conditions for good engineering practices.',18),
('a1000001-0000-0000-0000-000000000006','What does a SM model through their own behavior?','A new team member watches how you respond to a tense situation in Sprint Planning.','["Authority and control", "The Scrum values: commitment focus openness respect and courage", "Speed and efficiency above all else", "Deference to the most senior person in the room"]'::jsonb,1,'Scrum Masters embody Scrum values - their behavior models commitment openness respect focus and courage.',19);